; ============================================================================
; panel_orn — ORN_GLYPHS (row 17 ornament, 8 glyphs x 8 B = 64 B, src/level_defs.asm)
; GENERATED by tools/tiles_convert.py.  Source: concept panel_r4.tiles.  NOT tile ids;
; same on every level, attr = ATTR_FLOOR[depth] (default $0F shown).  Indices:
; 0=cap_l  1=link  2=bar  3=wing_l  4=skull_l  5=skull_r  6=wing_r  7=cap_r
; Row-17 layout (concept §3.3): cap_l, chain (link/bar alternating), wing_l skull_l
; skull_r wing_r at cols 14-17, chain, cap_r.  Boot copies orn_glyphs to ORN_GLYPHS.
; ============================================================================
orn_glyphs:
        DEFB $FF,$80,$B8,$A8,$A7,$BC,$80,$FF    ; 0 orn_cap_l
        DEFB $FF,$00,$7E,$81,$81,$7E,$00,$FF    ; 1 orn_link
        DEFB $FF,$00,$00,$FF,$FF,$00,$00,$FF    ; 2 orn_bar
        DEFB $FF,$03,$0F,$3D,$7B,$EF,$00,$FF    ; 3 orn_wing_l
        DEFB $FF,$0F,$1F,$19,$19,$0E,$05,$FF    ; 4 orn_skull_l
        DEFB $FF,$F0,$F8,$98,$98,$70,$A0,$FF    ; 5 orn_skull_r
        DEFB $FF,$C0,$F0,$BC,$DE,$F7,$00,$FF    ; 6 orn_wing_r
        DEFB $FF,$01,$1D,$15,$E5,$3D,$01,$FF    ; 7 orn_cap_r
orn_glyphs_end:
        ASSERT orn_glyphs_end - orn_glyphs == 64
ORN_CAP_L          EQU 0
ORN_LINK           EQU 1
ORN_BAR            EQU 2
ORN_WING_L         EQU 3
ORN_SKULL_L        EQU 4
ORN_SKULL_R        EQU 5
ORN_WING_R         EQU 6
ORN_CAP_R          EQU 7
